  }

  explicit binary_tree(T&& data) : data_(std::move(data)) {
  }

  binary_tree(const binary_tree&) = delete;
  binary_tree& operator=(const binary_tree&) = delete;
  binary_tree(binary_tree&&) = default;
  binary_tree& operator=(binary_tree&&) = default;

