    return left_;
  }

  node_ptr& right() {
    return right_;
  }

  const node_ptr& right() const {
    return right_;
  }

  void insert(const T& value) {
    if (!(data_ < value)) {
      if (left_) {
        left_->insert(value);
      } else {
        left_.reset(new binary_tree(value));
      }
    } else {
      if (right_) {
        right_->insert(value);
      } else {
        right_.reset(new binary_tree(value));
      }
    }
  }

  void insert(T&& value) {
    if (!(data_ < value)) {
      if (left_) {
        left_->insert(std::move(value));
      } else {
        left_.reset(new binary_tree(std::move(value)));
