#include "binary_search_tree.h"

#include <algorithm>
#include <cassert>
#include <iterator>
#include <memory>
#include <string>
#include <utility>
#include <vector>

using binary_search_tree::binary_tree;

template <typename T>
static std::vector<T> sorted_values(const binary_tree<T>& tree) {
  std::vector<T> result;
  for (const T& value : tree) {
    result.push_back(value);
  }
  return result;
}

struct MoveOnly {
  int key;
  explicit MoveOnly(int k) : key(k) {}
  MoveOnly(const MoveOnly&) = delete;
  MoveOnly& operator=(const MoveOnly&) = delete;
  MoveOnly(MoveOnly&&) = default;
  MoveOnly& operator=(MoveOnly&&) = default;
};

bool operator<(const MoveOnly& lhs, const MoveOnly& rhs) {
  return lhs.key < rhs.key;
}

bool operator==(const MoveOnly& lhs, const MoveOnly& rhs) {
  return lhs.key == rhs.key;
}

int main() {
  auto tree = std::unique_ptr<binary_tree<int>>(new binary_tree<int>(4));
  for (int value : {2, 6, 2, 1, 3, 5}) {
    tree->insert(value);
  }

  // Duplicates descend left, so the second 2 is the left child of the first 2.
  assert(tree->data() == 4);
  assert(tree->left()->data() == 2);
  assert(tree->left()->left()->data() == 2);
  assert(tree->left()->left()->left()->data() == 1);
  assert(tree->left()->right()->data() == 3);
  assert(tree->right()->left()->data() == 5);

  const std::vector<int> expected{1, 2, 2, 3, 4, 5, 6};
  assert(sorted_values(*tree) == expected);

  const auto& const_tree = *tree;
  assert(sorted_values(const_tree) == expected);
  assert(std::distance(tree->begin(), tree->end()) == 7);
  assert(std::distance(const_tree.begin(), const_tree.end()) == 7);
  assert(std::equal(expected.begin(), expected.end(), tree->cbegin()));

  auto it = tree->begin();
  auto previous = it++;
  assert(*previous == 1);
  assert(*it == 2);
  assert(previous != it);

  binary_tree<int> leaf(9);
  auto leaf_it = leaf.begin();
  assert(leaf_it != leaf.end());
  assert(*leaf_it == 9);
  ++leaf_it;
  assert(leaf_it == leaf.end());

  auto strings = std::unique_ptr<binary_tree<std::string>>(
      new binary_tree<std::string>("beta"));
  strings->insert(std::string("alpha"));
  strings->insert(std::string("gamma"));
  assert(sorted_values(*strings) ==
         (std::vector<std::string>{"alpha", "beta", "gamma"}));

  auto moved = std::unique_ptr<binary_tree<MoveOnly>>(
      new binary_tree<MoveOnly>(MoveOnly(3)));
  moved->insert(MoveOnly(1));
  moved->insert(MoveOnly(4));
  assert(sorted_values(*moved) ==
         (std::vector<MoveOnly>{MoveOnly(1), MoveOnly(3), MoveOnly(4)}));

  return 0;
}
